document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('a[href^="#"]').forEach(anchor=>{anchor.addEventListener('click',function(e){e.preventDefault();const target=document.querySelector(this.getAttribute('href'));if(target){target.scrollIntoView({behavior:'smooth',block:'start'})}})});const navBurger=document.querySelector('.navbar-burger');if(navBurger){navBurger.addEventListener('click',function(){this.classList.toggle('is-active');const menu=document.querySelector('.navbar-menu');if(menu){menu.classList.toggle('is-active')}})}const imageObserver=new IntersectionObserver((entries,observer)=>{entries.forEach(entry=>{if(entry.isIntersecting){const img=entry.target;if(img.dataset.src){img.src=img.dataset.src;img.removeAttribute('data-src');img.classList.add('loaded');observer.unobserve(img)}}})},{rootMargin:'50px 0px',threshold:0.01});document.querySelectorAll('img[data-src]').forEach(img=>{imageObserver.observe(img)});if('performance'in window){window.addEventListener('load',()=>{const loadTime=performance.timing.loadEventEnd-performance.timing.navigationStart;console.log(`Page loaded in ${loadTime}ms`)})}});function debounce(func,wait){let timeout;return function executedFunction(...args){const later=()=>{clearTimeout(timeout);func(...args)};clearTimeout(timeout);timeout=setTimeout(later,wait)}};